pragma solidity 0.8.25;

import "openzeppelin-contracts-5.0/access/Ownable.sol";
import "./IAuctionDepositVault.sol";

interface IAuctionEntryPoint {
    /* ========== STRUCT ========== */

    struct AuctionTx {
        bytes32 targetTxHash;
        uint256 blockNumber;
        address sender;
        address to;
        uint256 nonce;
        uint256 bid;
        uint256 callGasLimit;
